def match(orders):
    buy_book = []  # List of (price, arrival_time, id, qty) tuples, sorted by price desc then arrival_time asc
    sell_book = []  # List of (price, arrival_time, id, qty) tuples, sorted by price asc then arrival_time asc
    trades = []
    order_map = {}  # Maps id to (side, index_in_book) for tracking resting orders
    arrival_time = 0

    def match_buy(order_id, price, qty, is_market=False):
        nonlocal trades, arrival_time

        # Match against sell orders
        while qty > 0 and sell_book:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

            if not is_market and sell_price > price:
                break

            trade_qty = min(qty, sell_qty)
            trades.append([order_id, sell_id, sell_price, trade_qty])

            qty -= trade_qty
            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

            if sell_book[0][3] == 0:
                sell_book.pop(0)
                if sell_id in order_map:
                    del order_map[sell_id]

        return qty

    def match_sell(order_id, price, qty, is_market=False):
        nonlocal trades, arrival_time

        # Match against buy orders
        while qty > 0 and buy_book:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

            if not is_market and buy_price < price:
                break

            trade_qty = min(qty, buy_qty)
            trades.append([buy_id, order_id, buy_price, trade_qty])

            qty -= trade_qty
            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

            if buy_book[0][3] == 0:
                buy_book.pop(0)
                if buy_id in order_map:
                    del order_map[buy_id]

        return qty

    for order in orders:
        arrival_time += 1

        if order[0] == 'limit':
            _, order_id, side, price, qty = order

            if side == 'buy':
                remaining = match_buy(order_id, price, qty, is_market=False)
                if remaining > 0:
                    buy_book.append((price, arrival_time, order_id, remaining))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    order_map[order_id] = ('buy', order_id)
            else:  # sell
                remaining = match_sell(order_id, price, qty, is_market=False)
                if remaining > 0:
                    sell_book.append((price, arrival_time, order_id, remaining))
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    order_map[order_id] = ('sell', order_id)

        elif order[0] == 'ioc':
            _, order_id, side, price, qty = order

            if side == 'buy':
                match_buy(order_id, price, qty, is_market=False)
            else:  # sell
                match_sell(order_id, price, qty, is_market=False)

        elif order[0] == 'market':
            _, order_id, side, qty = order

            if side == 'buy':
                match_buy(order_id, float('inf'), qty, is_market=True)
            else:  # sell
                match_sell(order_id, 0, qty, is_market=True)

        elif order[0] == 'cancel':
            _, order_id = order

            if order_id in order_map:
                side, _ = order_map[order_id]

                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != order_id]
                else:  # sell
                    sell_book[:] = [o for o in sell_book if o[2] != order_id]

                del order_map[order_id]

    return trades

